local _, WFJ = ...
WFJ.Data.add("book", {
  ["614910a914a588c6"] = { "Appena si è presentata l'occasione, gli ho affondato il pugnale nella schiena! I suoi polmoni hanno ceduto subito sotto la forza del colpo, e il cadavere è crollato a terra con un tonfo sordo.\n\nL'imboscata era stata così rapida e violenta che il povero sciocco non ha avuto nemmeno il tempo di urlare di dolore. Stranamente, quando ho estratto la lama dalla sua schiena, dalla sentinella trafitta è uscito un odore nauseabondo.", "." },
  ["614c7b469ac667c4"] = { "Fratello Neals,\n\nla mia uva è salva! {name}, il latore di questo bollettino, ha sfidato la mia vigna infestata dai delinquenti e ha raccolto l'uva che io non potevo raccogliere. Anche se i Defias si aggirano ancora oltre il fiume, quasi tutto il raccolto è stato salvato.\n\nPuoi aggiungere alle tue scorte un carico completo di ceste d'uva.\n\nChe la Luce ci protegga,\n-Milly Osworth", "." },
  ["61aec76e685b6213"] = { "Proprio mentre stavo per chiedere ad Ajeck come mai non mostrasse interesse per la strategia di caccia della giornata, lei prese la faretra, estrasse una freccia e scoccò un tiro dritto verso il povero Barnil. Ma non era Barnil il bersaglio di Ajeck. Perché quando Barnil si scostò, a bocca aperta, un grosso crocolisco di fiume venne a galla con la freccia di Ajeck piantata alla perfezione fra i suoi due grandi occhi.", "." },
  ["61ebc47d1f6fdf0d"] = { ". . .Giles, il ragazzo, sembra piuttosto turbolento e non sarà facile da educare. La figlia maggiore, Tilloa, sembra invece eccezionalmente intelligente. Non ho potuto fare a meno di notare anche la sua bellezza ammaliante. Ormai è sulla soglia dell'età da donna. A quanto pare il signore ha già combinato il suo matrimonio per l'anno prossimo. Ma divago. Questa settimana accompagnerò la famiglia nella loro casa estiva vicino al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧, a Elwynn, non lontano dalle Montagne Crestarossa. Spero di scrivere ancora mentre sarò lì.", "." },
  ["61f2040c81f8cd28"] = { "Altre citazioni!\n\n\"Conoscete quella sensazione che si prova quando si finisce di costruire qualcosa e lo si accende per la prima volta, sentendo la potenza e la gioia dell'invenzione mentre il congegno prende vita? Gli gnomi no.\"\n\n-- Nixx Sprocketspring, maestro di ⟦Goblin Engineer=Ingegneria dei Goblin⟧ di ⟦Gadgetzan=Meccania⟧\n\n\"L'ingegneria consiste nel prendere la fantasia e renderla fantastica!\"\n\n-- Rovis McCrankenspank, inventore gnomo", "." },
  ["61fe582121c8e6fd"] = { "Nelle pagine seguenti troverai un elenco dei materiali necessari per creare l'armatura temprata dal fuoco. Buona fortuna, combattente.\n\n-Furen Longbeard", "." },
})
